// ========================================
// STEP 1: Extract Video ID from YouTube URL
// Supports: youtube.com/watch?v=, youtu.be/, /embed/, /shorts/
// ========================================
const url = $input.first().json.youtube_url;

const regex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?|shorts)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/;
const match = url.match(regex);

if (!match || !match[1]) {
  throw new Error('Invalid YouTube URL. Must be a valid youtube.com or youtu.be link. Got: ' + url);
}

const videoId = match[1];
console.log('Extracted Video ID:', videoId);

return [
  {
    json: {
      videoId: videoId,
      youtube_url: url
    }
  }
];

// ========================================
// STEP 2: Clean and normalize the transcript
// Handles multiple response formats from Supadata API
// ========================================
const data = $input.first().json;
console.log('Raw transcript response keys:', Object.keys(data));

let transcript = '';

// Handle Supadata response format
if (data.content && Array.isArray(data.content)) {
  // Array of { text, offset, duration } objects
  transcript = data.content.map(segment => segment.text || '').join(' ');
} else if (data.transcript && typeof data.transcript === 'string') {
  transcript = data.transcript;
} else if (data.text) {
  transcript = data.text;
} else if (typeof data === 'string') {
  transcript = data;
} else {
  // Last resort: stringify and use it
  const raw = JSON.stringify(data);
  throw new Error('Unexpected transcript format. Raw response: ' + raw.substring(0, 300));
}

// Clean the transcript
transcript = transcript
  .replace(/\[Music\]/gi, '')
  .replace(/\[Applause\]/gi, '')
  .replace(/\[Laughter\]/gi, '')
  .replace(/\[.*?\]/g, '')          // Remove any [bracket] annotations
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&#39;/g, "'")
  .replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ')             // Collapse whitespace
  .trim();

// Limit to ~3500 chars to stay within OpenRouter token budget
const MAX_CHARS = 3500;
if (transcript.length > MAX_CHARS) {
  transcript = transcript.substring(0, MAX_CHARS) + '... [transcript truncated]';
}

console.log('Cleaned transcript length:', transcript.length, 'chars');

if (transcript.length < 50) {
  throw new Error('Transcript too short or empty. Video may have no captions. Length: ' + transcript.length);
}

return [
  {
    json: {
      transcript: transcript,
      transcriptLength: transcript.length
    }
  }
];

