// ========================================
// STEP 3: Parse LinkedIn posts from AI response
// ========================================
const response = $input.first().json;

if (!response.choices || !response.choices[0]) {
  throw new Error('OpenRouter returned no choices. Full response: ' + JSON.stringify(response).substring(0, 300));
}

const rawText = response.choices[0].message.content;
console.log('LinkedIn raw AI response (first 300 chars):', rawText.substring(0, 300));

const posts = [];

// Primary parser: look for POST1:, POST2: etc
const postRegex = /POST(\d+):[\s\S]*?(?=POST\d+:|$)/gi;
let match;

while ((match = postRegex.exec(rawText)) !== null) {
  const content = match[0]
    .replace(/^POST\d+:\s*/i, '')
    .trim();

  if (content && content.length > 30) {
    posts.push({
      json: {
        platform: 'linkedin',
        postNumber: parseInt(match[1]),
        content: content,
        charCount: content.length,
        status: 'pending_review'
      }
    });
  }
}

// Fallback parser: split by double newlines if primary fails
if (posts.length === 0) {
  console.log('Primary parser failed, using fallback...');
  const chunks = rawText.split(/\n{2,}/).filter(c => c.trim().length > 80);
  chunks.slice(0, 5).forEach((chunk, i) => {
    posts.push({
      json: {
        platform: 'linkedin',
        postNumber: i + 1,
        content: chunk.trim(),
        charCount: chunk.trim().length,
        status: 'pending_review',
        parsedViaFallback: true
      }
    });
  });
}

console.log('Parsed LinkedIn posts:', posts.length);

if (posts.length === 0) {
  throw new Error('Could not parse any LinkedIn posts from AI response. Raw: ' + rawText.substring(0, 500));
}

return posts;

// ========================================
// STEP 4: Parse Twitter threads from AI response
// ========================================
const response = $input.first().json;

if (!response.choices || !response.choices[0]) {
  throw new Error('OpenRouter returned no choices for Twitter. Full response: ' + JSON.stringify(response).substring(0, 300));
}

const rawText = response.choices[0].message.content;
console.log('Twitter raw AI response (first 300 chars):', rawText.substring(0, 300));

const threads = [];

// Primary parser: extract THREAD1:, THREAD2: etc
const threadRegex = /THREAD(\d+):[\s\S]*?(?=THREAD\d+:|$)/gi;
let threadMatch;

while ((threadMatch = threadRegex.exec(rawText)) !== null) {
  const threadBody = threadMatch[0].replace(/^THREAD\d+:\s*/i, '').trim();
  const tweets = [];

  // Extract individual tweets
  const tweetRegex = /Tweet(\d+):\s*(.+?)(?=Tweet\d+:|$)/gis;
  let tweetMatch;

  while ((tweetMatch = tweetRegex.exec(threadBody)) !== null) {
    const tweetContent = tweetMatch[2].trim();
    if (tweetContent.length > 0 && tweetContent.length <= 280) {
      tweets.push(tweetContent);
    } else if (tweetContent.length > 280) {
      // Truncate tweets over character limit
      tweets.push(tweetContent.substring(0, 277) + '...');
    }
  }

  if (tweets.length > 0) {
    threads.push({
      json: {
        platform: 'twitter',
        threadNumber: parseInt(threadMatch[1]),
        tweets: tweets,
        fullThread: tweets.map((t, i) => `${i+1}/${tweets.length} ${t}`).join('\n\n'),
        tweetCount: tweets.length,
        status: 'pending_review'
      }
    });
  }
}

// Fallback: use entire response as one thread
if (threads.length === 0) {
  console.log('Thread parser failed, using fallback...');
  threads.push({
    json: {
      platform: 'twitter',
      threadNumber: 1,
      tweets: [rawText.trim().substring(0, 270)],
      fullThread: rawText.trim().substring(0, 270),
      tweetCount: 1,
      status: 'pending_review',
      parsedViaFallback: true
    }
  });
}

console.log('Parsed Twitter threads:', threads.length);
return threads;

// ========================================
// STEP 5: Log all posts before scheduling
// REVIEW these in execution logs before enabling Buffer!
// ========================================
const items = $input.all();

console.log('\n========== GHOSTPOSTER REVIEW ==========');
console.log(`Total posts ready to schedule: ${items.length}`);
console.log('');

items.forEach((item, idx) => {
  const d = item.json;
  console.log(`--- Post ${idx + 1} [${d.platform.toUpperCase()}] ---`);
  if (d.platform === 'linkedin') {
    console.log(`Post #${d.postNumber}:`);
    console.log(d.content);
  } else {
    console.log(`Thread #${d.threadNumber} (${d.tweetCount} tweets):`);
    console.log(d.fullThread);
  }
  console.log('');
});

console.log('=========================================');

// Pass through all items unchanged
return items;

const items = $input.all();

let body = 'GHOSTPOSTER ENGINE - POSTS READY\n\n';
body += '==================================================\n\n';

const linkedin = items.filter(i => i.json.platform === 'linkedin');
const twitter = items.filter(i => i.json.platform === 'twitter');

body += 'LINKEDIN POSTS (' + linkedin.length + ')\n';
body += '==================================================\n\n';

linkedin.forEach((item, idx) => {
  body += 'POST ' + (idx + 1) + ':\n';
  body += item.json.content + '\n\n';
  body += '--------------------------------------------------\n\n';
});

body += 'TWITTER THREADS (' + twitter.length + ')\n';
body += '==================================================\n\n';

twitter.forEach((item, idx) => {
  body += 'THREAD ' + (idx + 1) + ':\n';
  item.json.tweets.forEach((tweet, ti) => {
    body += (ti + 1) + '. ' + tweet + '\n';
  });
  body += '\n--------------------------------------------------\n\n';
});

return [{
  json: {
    subject: 'Ghostposter: ' + (linkedin.length + twitter.length) + ' posts ready to publish',
    body: body,
    totalPosts: items.length
  }
}];
